/** Regenerates docs/FACT_CHECK.md from the content tables. */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { collectFacts } from '../src/data/validate.ts';

const facts = collectFacts();
const pending = facts.filter((f) => f.fact.needsReview);

const lines = [
  '# Fact check',
  '',
  '> Generated by `npm run factcheck` from the tables in `src/data/`. Do not edit by hand.',
  '',
  'Every real-world claim the player can read is listed here while it has `needsReview: true`.',
  'Nothing in the game is verified until a human checks the claim and sets `needsReview: false` in the data.',
  '',
  '**Verify current star counts before sharing.** (Applies to the tasting-menu restaurants once they are added.)',
  '',
  `Pending review: ${pending.length} of ${facts.length} claims.`,
  '',
  '| Table | ID | Shown as | Claim | Source |',
  '| --- | --- | --- | --- | --- |',
  ...pending.map(
    (f) => `| ${f.table} | \`${f.id}\` | ${f.name} | ${f.fact.text.replace(/\|/g, '\\|')} | ${f.fact.source} |`,
  ),
  '',
];

const out = fileURLToPath(new URL('../docs/FACT_CHECK.md', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out} (${pending.length} pending).`);
